    final cloud = get?.call('JIRA_CLOUD')?.toLowerCase() == 'true' ||
        url.contains('atlassian.net');
    return cloud
        ? SyncRetryPolicy.forJiraCloud(random)
        : SyncRetryPolicy.fromEnvironment(get, random);
