+        jsonDecode(bridge.execute('file_exists', {'path': file.path})),
+        {'exists': true},
+      );
+      expect(
+        jsonDecode(bridge.execute('file_exists', {'path': '${dir.path}/nope'})),
+        {'exists': false},
+      );
+    });
+  });
+}
