  /// ids), so an ephemeral port like 50312 misfired the old "503"
  /// substring check and retried a 400 five times.
  bool isRetryableStatus(int status, [String? body]) {
    if (status == 429 || status == 502 || status == 503 || status == 504) {
      return true;
